insert into public.activities(id,lesson_id,title,instructions,activity_type,activity_order) values('00444c5e-d0a2-3d43-95cd-50c636c9618d','8eae21b8-7941-0081-71f4-f5c703d88398','Listen and recognize','Use the existing Korean browser voice when available, then choose the phrase meaning. If no Korean voice is installed, read aloud and use vocabulary review; no audio recording or listening score is claimed.','listening',3) on conflict(id) do nothing;
