insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('f289b8ea-b199-acb1-fda2-27e4427cd778','2672a9b8-8415-96c6-1c45-4178afe19675','At Incheon Airport, what does “안녕하세요” communicate?','multiple_choice','Hello (polite)','["Hello (polite)","Goodbye (to someone leaving)","Goodbye (to someone staying)"]'::jsonb,'안녕하세요: Hello (polite). Review the unit’s taught patterns. No new grammar is required.',1) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('80e2cf27-176b-ee6d-f097-c16633f1fec5','2672a9b8-8415-96c6-1c45-4178afe19675','At Incheon Airport, what does “안녕히 가세요” communicate?','multiple_choice','Goodbye (to someone leaving)','["Goodbye (to someone leaving)","Hello (polite)","Goodbye (to someone staying)"]'::jsonb,'안녕히 가세요: Goodbye (to someone leaving). Review the unit’s taught patterns. No new grammar is required.',2) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('bb68fa93-6a7e-9ec3-1548-9492ac55d2f9','2672a9b8-8415-96c6-1c45-4178afe19675','At Incheon Airport, what does “안녕히 계세요” communicate?','multiple_choice','Goodbye (to someone staying)','["Goodbye (to someone staying)","Hello (polite)","Goodbye (to someone leaving)"]'::jsonb,'안녕히 계세요: Goodbye (to someone staying). Review the unit’s taught patterns. No new grammar is required.',3) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('8986b88f-4f0f-3b65-7c35-7c6626d248f4','2672a9b8-8415-96c6-1c45-4178afe19675','Ace asks you to communicate: “Hello. It is nice to meet you.” Which Korean response fits?','multiple_choice','안녕하세요. 만나서 반가워요.','["안녕하세요. 만나서 반가워요.","저는 민수예요. 학생이에요.","물 주세요. 감사합니다."]'::jsonb,'안녕하세요. 만나서 반가워요. — Hello. It is nice to meet you.. Learn greetings as whole expressions. 안녕하세요 is a polite greeting. Say 안녕히 가세요 to someone leaving, and 안녕히 계세요 to someone staying. These are not interchangeable.',4) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('bc568217-a027-04de-2ab5-fc76c8a5a7ad','2672a9b8-8415-96c6-1c45-4178afe19675','Ace asks you to communicate: “I am Minsu. I am a student.” Which Korean response fits?','multiple_choice','저는 민수예요. 학생이에요.','["저는 민수예요. 학생이에요.","안녕하세요. 만나서 반가워요.","물 주세요. 감사합니다."]'::jsonb,'저는 민수예요. 학생이에요. — I am Minsu. I am a student.. 저는 marks a humble first-person topic. After a noun with a final consonant use 이에요; after a vowel use 예요. Names vary: 민수예요, 지민이에요. Do not add 입니다 and 이에요 together.',5) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('c67b20ea-4a32-4b93-2f3e-69802aacd51f','2672a9b8-8415-96c6-1c45-4178afe19675','Ace asks you to communicate: “Please give me water. Thank you.” Which Korean response fits?','multiple_choice','물 주세요. 감사합니다.','["물 주세요. 감사합니다.","안녕하세요. 만나서 반가워요.","저는 민수예요. 학생이에요."]'::jsonb,'물 주세요. 감사합니다. — Please give me water. Thank you.. Noun + 주세요 requests something politely: 물 주세요. English please has no single Korean equivalent for every situation. 잠시만요 gets attention or asks someone to wait; 죄송해요 apologizes.',6) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('63a2f484-ecdf-e54f-9854-c6b8727782b4','2672a9b8-8415-96c6-1c45-4178afe19675','Ace asks you to communicate: “Please say it again. Please speak slowly.” Which Korean response fits?','multiple_choice','다시 말해 주세요. 천천히 말해 주세요.','["다시 말해 주세요. 천천히 말해 주세요.","안녕하세요. 만나서 반가워요.","저는 민수예요. 학생이에요."]'::jsonb,'다시 말해 주세요. 천천히 말해 주세요. — Please say it again. Please speak slowly.. 네 and 아니요 respond to the speaker’s proposition; negative questions do not map neatly to English yes/no. First practice positive questions. 천천히 말해 주세요 is a memorized request; verb formation comes later.',7) on conflict(id) do nothing;
insert into public.travel_country_units(country_id,unit_id,is_required) values('d3c981a5-9bf7-469c-93de-8a7c5105c6eb','e33f7bfa-d32c-c894-1d1b-127883930e64',true) on conflict do nothing;
