insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('cc38b957-84ce-110e-35f4-55fa49f12d66','423f4a1e-720a-fa37-872a-4662a79caef1','Ace asks you to communicate: “I am learning Hangul.” Which Korean response fits?','multiple_choice','한글을 배워요.','["한글을 배워요.","가, 나, 다, 마를 읽어요.","나무, 바다, 우유를 읽어요."]'::jsonb,'한글을 배워요. — I am learning Hangul.. A block has an initial consonant and a vowel, with an optional final consonant. Initial ㅇ is silent in 아; final ㅇ is ng in 강. Read blocks left to right.',4) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('562d6ca1-52de-2c1f-5513-d0f834e6c3c8','423f4a1e-720a-fa37-872a-4662a79caef1','Ace asks you to communicate: “I read ga, na, da, and ma.” Which Korean response fits?','multiple_choice','가, 나, 다, 마를 읽어요.','["가, 나, 다, 마를 읽어요.","한글을 배워요.","나무, 바다, 우유를 읽어요."]'::jsonb,'가, 나, 다, 마를 읽어요. — I read ga, na, da, and ma.. Start with ㄱ ㄴ ㄷ ㄹ ㅁ ㅂ ㅅ ㅇ ㅈ ㅊ ㅋ ㅌ ㅍ ㅎ and ten basic vowels. ㄱ is not always English g or k; sound depends on position. ㅓ and ㅡ need listening rather than English spelling analogies.',5) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('ac320080-cc70-6c05-fc21-153f7437c478','423f4a1e-720a-fa37-872a-4662a79caef1','Ace asks you to communicate: “I read tree, sea, and milk.” Which Korean response fits?','multiple_choice','나무, 바다, 우유를 읽어요.','["나무, 바다, 우유를 읽어요.","한글을 배워요.","가, 나, 다, 마를 읽어요."]'::jsonb,'나무, 바다, 우유를 읽어요. — I read tree, sea, and milk.. With ㅏ, put the consonant to its left: ㄴ + ㅏ = 나. With ㅗ, put it above: ㄱ + ㅗ = 고. A final consonant sits below: ㄱ + ㅏ + ㅇ = 강. Do not arrange jamo as a flat Latin-letter string.',6) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('a0e10d63-5322-39e7-af8f-775859170a94','423f4a1e-720a-fa37-872a-4662a79caef1','Ace asks you to communicate: “Where is the exit?” Which Korean response fits?','multiple_choice','출구가 어디예요?','["출구가 어디예요?","한글을 배워요.","가, 나, 다, 마를 읽어요."]'::jsonb,'출구가 어디예요? — Where is the exit?. Read one block at a time, then a whole word. 역 means station; 서울역 is Seoul Station. 입구 and 출구 are opposites. Keep spaces between Korean words, not between every block.',7) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('f48ee5e8-de05-7879-072a-54be143920ee','423f4a1e-720a-fa37-872a-4662a79caef1','Remember your visit to Incheon Airport: what does “안녕하세요” mean?','multiple_choice','Hello (polite)','["Hello (polite)","Goodbye (to someone leaving)","Goodbye (to someone staying)"]'::jsonb,'From “Saying Hello”: 안녕하세요 means Hello (polite).',8) on conflict(id) do nothing;
