insert into public.activities(id,lesson_id,title,instructions,activity_type,activity_order) values('97939cfd-207a-be64-51d0-2e418bc68601','1d2d0db8-df77-e695-a1cf-1e1b27633496','Notice, understand, and speak','에서 marks a source in 왔어요 (came). Learn 어디에서 왔어요? as a useful past-tense chunk; productive past tense is taught in Unit 7. 한국 사람이에요 identifies nationality, not language ability.
