insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('b2db8b86-8aa3-548f-8122-cddbc896aeb3','fca8ff7a-5508-47d9-a6e9-3135722132f3','At Hongdae, what does “음악” communicate?','multiple_choice','music','["music","like (polite)","do not like (polite)"]'::jsonb,'음악: music. Attach 을 after a final consonant and 를 after a vowel to the object of 좋아해요: 음악을 좋아해요, 커피를 좋아해요. The predicate usually comes last. 안 before a verb gives basic negation: 안 좋아해요.',3) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('72e1fd24-df55-2190-6ed8-c290da54c796','fca8ff7a-5508-47d9-a6e9-3135722132f3','Ace asks you to communicate: “I like music.” Which Korean response fits?','multiple_choice','저는 음악을 좋아해요.','["저는 음악을 좋아해요.","필리핀에서 왔어요.","저는 학생이에요. 선생님이 아니에요."]'::jsonb,'저는 음악을 좋아해요. — I like music.. Attach 을 after a final consonant and 를 after a vowel to the object of 좋아해요: 음악을 좋아해요, 커피를 좋아해요. The predicate usually comes last. 안 before a verb gives basic negation: 안 좋아해요.',4) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('467cf667-b2b5-5969-2589-93f0120d4704','fca8ff7a-5508-47d9-a6e9-3135722132f3','Read “저는 음악을 좋아해요.”. Which meaning fits this exchange?','multiple_choice','I like music.','["I like music.","I came from the Philippines.","I am a student. I am not a teacher."]'::jsonb,'Attach 을 after a final consonant and 를 after a vowel to the object of 좋아해요: 음악을 좋아해요, 커피를 좋아해요. The predicate usually comes last. 안 before a verb gives basic negation: 안 좋아해요.',5) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('e5f90d2b-4f5b-08a1-a853-8e6b86bba3a3','fca8ff7a-5508-47d9-a6e9-3135722132f3','Remember your visit to Hangul Discovery Center: what does “입구” mean?','multiple_choice','entrance','["entrance","exit","station"]'::jsonb,'From “Read Signs and Everyday Words”: 입구 means entrance.',6) on conflict(id) do nothing;
