insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('059091e8-d855-e702-2bb8-69e3ca982221','341c7709-23ed-4454-cc91-e7aa9dd4d317','At Hongdae, what does “어디에서 왔어요?” communicate?','multiple_choice','Where are you from?','["Where are you from?","where","the Philippines"]'::jsonb,'어디에서 왔어요?: Where are you from?. Review the unit’s taught patterns. No new grammar is required.',2) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('7a25a0d4-1a24-2dee-f8af-0467456c7b30','341c7709-23ed-4454-cc91-e7aa9dd4d317','At Hongdae, what does “필리핀” communicate?','multiple_choice','the Philippines','["the Philippines","where","Where are you from?"]'::jsonb,'필리핀: the Philippines. Review the unit’s taught patterns. No new grammar is required.',3) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('4e7fcd7e-e034-f5d8-e6e4-ffe30b16b083','341c7709-23ed-4454-cc91-e7aa9dd4d317','Ace asks you to communicate: “I came from the Philippines.” Which Korean response fits?','multiple_choice','필리핀에서 왔어요.','["필리핀에서 왔어요.","저는 학생이에요. 선생님이 아니에요.","이거 뭐예요? 책이에요."]'::jsonb,'필리핀에서 왔어요. — I came from the Philippines.. 에서 marks a source in 왔어요 (came). Learn 어디에서 왔어요? as a useful past-tense chunk; productive past tense is taught in Unit 7. 한국 사람이에요 identifies nationality, not language ability.',4) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('b61bf3c7-add6-ebd4-784e-ccb5c078c3b7','341c7709-23ed-4454-cc91-e7aa9dd4d317','Ace asks you to communicate: “I am a student. I am not a teacher.” Which Korean response fits?','multiple_choice','저는 학생이에요. 선생님이 아니에요.','["저는 학생이에요. 선생님이 아니에요.","필리핀에서 왔어요.","이거 뭐예요? 책이에요."]'::jsonb,'저는 학생이에요. 선생님이 아니에요. — I am a student. I am not a teacher.. 뭐 해요? may ask what someone does or is doing; context matters. Use 직업이 뭐예요? for occupation. Noun + 이/가 아니에요 negates identification: 학생이 아니에요.',5) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('b91da818-ca65-034c-a562-97489641302b','341c7709-23ed-4454-cc91-e7aa9dd4d317','Ace asks you to communicate: “What is this? It is a book.” Which Korean response fits?','multiple_choice','이거 뭐예요? 책이에요.','["이거 뭐예요? 책이에요.","필리핀에서 왔어요.","저는 학생이에요. 선생님이 아니에요."]'::jsonb,'이거 뭐예요? 책이에요. — What is this? It is a book.. 이거 is this near the speaker; 그거 is that near the listener or already mentioned; 저거 is that over there away from both. A question can keep the statement word order with rising intonation.',6) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('3f3f7d42-41c4-254e-3cd1-093dfbbf2f72','341c7709-23ed-4454-cc91-e7aa9dd4d317','Ace asks you to communicate: “I like music.” Which Korean response fits?','multiple_choice','저는 음악을 좋아해요.','["저는 음악을 좋아해요.","필리핀에서 왔어요.","저는 학생이에요. 선생님이 아니에요."]'::jsonb,'저는 음악을 좋아해요. — I like music.. Attach 을 after a final consonant and 를 after a vowel to the object of 좋아해요: 음악을 좋아해요, 커피를 좋아해요. The predicate usually comes last. 안 before a verb gives basic negation: 안 좋아해요.',7) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('38417db0-f211-394b-323f-1e4c97931378','341c7709-23ed-4454-cc91-e7aa9dd4d317','Remember your visit to Hangul Discovery Center: what does “한글” mean?','multiple_choice','Hangul','["Hangul","consonant","vowel"]'::jsonb,'From “Meet Hangul”: 한글 means Hangul.',8) on conflict(id) do nothing;
insert into public.travel_country_units(country_id,unit_id,is_required) values('d3c981a5-9bf7-469c-93de-8a7c5105c6eb','45c2c8bd-f990-df8b-e110-a16d929fe334',true) on conflict do nothing;
