insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('4491d7a4-6e74-1665-2394-bd31588cebdc','9869a48a-750c-4da4-c5c3-a3fc4dbf52ee','At Myeongdong, what does “하나” communicate?','multiple_choice','one (native)','["one (native)","two (native)","three (native)"]'::jsonb,'하나: one (native). Review the unit’s taught patterns. No new grammar is required.',1) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('4c91bdac-4f1e-914b-efb6-12b72c84929c','9869a48a-750c-4da4-c5c3-a3fc4dbf52ee','At Myeongdong, what does “둘” communicate?','multiple_choice','two (native)','["two (native)","one (native)","three (native)"]'::jsonb,'둘: two (native). Review the unit’s taught patterns. No new grammar is required.',2) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('601b115f-3e54-a433-f9db-2494f7901007','9869a48a-750c-4da4-c5c3-a3fc4dbf52ee','At Myeongdong, what does “셋” communicate?','multiple_choice','three (native)','["three (native)","one (native)","two (native)"]'::jsonb,'셋: three (native). Review the unit’s taught patterns. No new grammar is required.',3) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('db152573-e856-d61d-ec85-2e2a6c9c9a43','9869a48a-750c-4da4-c5c3-a3fc4dbf52ee','Ace asks you to communicate: “Please give me two.” Which Korean response fits?','multiple_choice','두 개 주세요.','["두 개 주세요.","삼천 원이에요.","이거 얼마예요? 카드로 계산할게요."]'::jsonb,'두 개 주세요. — Please give me two.. 하나, 둘, 셋, 넷 become 한, 두, 세, 네 before many counters. Learn 개 as a general item counter: 한 개, 두 개. Prices use a different system in the next lesson.',4) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('7f1033c4-28e5-b446-aeb6-c2081a8e247b','9869a48a-750c-4da4-c5c3-a3fc4dbf52ee','Ace asks you to communicate: “It is three thousand won.” Which Korean response fits?','multiple_choice','삼천 원이에요.','["삼천 원이에요.","두 개 주세요.","이거 얼마예요? 카드로 계산할게요."]'::jsonb,'삼천 원이에요. — It is three thousand won.. 십 is ten, 이십 is twenty, 백 is one hundred, 천 is one thousand. 삼천 원 is 3,000 won. Do not use native 셋 for 삼천. 구 and 십 extend the sequence to nine and ten.',5) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('19c1d767-3457-7275-a947-0b6bc6d89c3b','9869a48a-750c-4da4-c5c3-a3fc4dbf52ee','Ace asks you to communicate: “How much is this? I will pay by card.” Which Korean response fits?','multiple_choice','이거 얼마예요? 카드로 계산할게요.','["이거 얼마예요? 카드로 계산할게요.","두 개 주세요.","삼천 원이에요."]'::jsonb,'이거 얼마예요? 카드로 계산할게요. — How much is this? I will pay by card.. 얼마예요? asks a price, while 몇 asks how many before a counter. 카드로 means by card; 로 follows a vowel or ㄹ, 으로 follows other final consonants. Treat 카드로 as a chunk here.',6) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('56b70e95-60df-7c78-874e-858f66b8a978','9869a48a-750c-4da4-c5c3-a3fc4dbf52ee','Ace asks you to communicate: “Do you have a small bag?” Which Korean response fits?','multiple_choice','작은 가방 있어요?','["작은 가방 있어요?","두 개 주세요.","삼천 원이에요."]'::jsonb,'작은 가방 있어요? — Do you have a small bag?. 있어요? asks whether something exists or is available. 없어요 says it is unavailable. 작은 and 큰 describe a small or big item; learn these useful attributive forms before broader adjective conjugation.',7) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('57b167e1-21df-4b91-cd83-2b5bc360adb2','9869a48a-750c-4da4-c5c3-a3fc4dbf52ee','Remember your visit to Hongdae: what does “어디” mean?','multiple_choice','where','["where","Where are you from?","the Philippines"]'::jsonb,'From “Where Are You From?”: 어디 means where.',8) on conflict(id) do nothing;
