insert into public.units(id,course_id,title,description,unit_order,location_name,is_published) values('72d03195-6bab-12c9-b31c-0b41e4b42bc4','a5c6b836-c1a8-70e6-b53b-cd1742d46707','Taste of Korea','Food names do not reliably identify every ingredient. Ask staff about ingredients and allergies; do not assume a dish is vegetarian or allergen-free.',5,'Gwangjang Market',false) on conflict(id) do nothing;
