insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('091de9b5-efec-697d-4fed-bd1080671dfb','c9dc0c73-a504-1c46-7d7f-37edfdb066e5','Ace asks you to communicate: “What is this? It is gimbap.” Which Korean response fits?','multiple_choice','이거 뭐예요? 김밥이에요.','["이거 뭐예요? 김밥이에요.","김밥하고 물 주세요.","커피 두 잔 주세요."]'::jsonb,'이거 뭐예요? 김밥이에요. — What is this? It is gimbap.. 뭐예요? identifies food. 들어가요? asks whether an ingredient goes into it. Learn 고기가 들어가요? as a safety-oriented question; recipes vary by vendor.',4) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('b10da67b-69e5-a6b0-a671-cbd3c8591ce2','c9dc0c73-a504-1c46-7d7f-37edfdb066e5','Ace asks you to communicate: “Please give me gimbap and water.” Which Korean response fits?','multiple_choice','김밥하고 물 주세요.','["김밥하고 물 주세요.","이거 뭐예요? 김밥이에요.","커피 두 잔 주세요."]'::jsonb,'김밥하고 물 주세요. — Please give me gimbap and water.. Noun + 주세요 is a polite order. 하고 connects nouns in everyday speech: 김밥하고 물 주세요. 고기를 안 먹어요 says I do not eat meat, not that the dish contains none.',5) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('caa03263-0088-7e45-8dbe-3b46d0c79db8','c9dc0c73-a504-1c46-7d7f-37edfdb066e5','Ace asks you to communicate: “Two cups of coffee, please.” Which Korean response fits?','multiple_choice','커피 두 잔 주세요.','["커피 두 잔 주세요.","이거 뭐예요? 김밥이에요.","김밥하고 물 주세요."]'::jsonb,'커피 두 잔 주세요. — Two cups of coffee, please.. Use 잔 for cups/glasses, 병 for bottles, and 개 for general items. 한 잔, 두 잔, 세 잔, 네 잔 use shortened native numbers. 한 명 counts a person; do not substitute it for a cup.',6) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('5ea192a0-4873-8412-384a-87c1dae365d3','c9dc0c73-a504-1c46-7d7f-37edfdb066e5','Ace asks you to communicate: “It is delicious. It is a little spicy.” Which Korean response fits?','multiple_choice','맛있어요. 조금 매워요.','["맛있어요. 조금 매워요.","이거 뭐예요? 김밥이에요.","김밥하고 물 주세요."]'::jsonb,'맛있어요. 조금 매워요. — It is delicious. It is a little spicy.. 맛있어요 means tastes good; 맵다 becomes 매워요, not 맙어요. Descriptive predicates do not need an extra 이에요. 덜 맵게 해 주세요 is a useful request; a vendor may be unable to alter a prepared dish.',7) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('7cd33327-803d-bc9d-055b-2fecd636f27b','c9dc0c73-a504-1c46-7d7f-37edfdb066e5','Remember your visit to Myeongdong: what does “하나” mean?','multiple_choice','one (native)','["one (native)","two (native)","three (native)"]'::jsonb,'From “Native Korean Numbers”: 하나 means one (native).',8) on conflict(id) do nothing;
insert into public.travel_country_units(country_id,unit_id,is_required) values('d3c981a5-9bf7-469c-93de-8a7c5105c6eb','72d03195-6bab-12c9-b31c-0b41e4b42bc4',true) on conflict do nothing;
