insert into public.units(id,course_id,title,description,unit_order,location_name,is_published) values('434cea26-e16b-8e01-a7fd-159244e28e1a','a5c6b836-c1a8-70e6-b53b-cd1742d46707','Getting Around Korea','Follow station signage and priority seating rules. Check the line and direction; a station name alone does not identify the correct platform.',6,'Seoul Subway',false) on conflict(id) do nothing;
