insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('7c53a9c2-fe41-6afc-48c1-77712b9af449','758e97c1-920d-b433-cd55-438c66d327ef','At Seoul Subway, what does “왼쪽” communicate?','multiple_choice','left side','["left side","right side","front"]'::jsonb,'왼쪽: left side. 쪽 means side/direction. 왼쪽으로 가세요 means please go left. 으로/로 marks a direction or means. 쭉 가세요 means go straight along; it is not a fixed distance.',1) on conflict(id) do nothing;
