insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('4fb0aec1-a32d-b145-381d-abe48d65ee60','758e97c1-920d-b433-cd55-438c66d327ef','Ace asks you to communicate: “Go straight. Turn/go right.” Which Korean response fits?','multiple_choice','쭉 가세요. 오른쪽으로 가세요.','["쭉 가세요. 오른쪽으로 가세요.","역에 가요.","지하철을 타요. 서울역에서 내려요."]'::jsonb,'쭉 가세요. 오른쪽으로 가세요. — Go straight. Turn/go right.. 쪽 means side/direction. 왼쪽으로 가세요 means please go left. 으로/로 marks a direction or means. 쭉 가세요 means go straight along; it is not a fixed distance.',4) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('69f6c1b8-1b69-be33-6301-3c62dccee5cb','758e97c1-920d-b433-cd55-438c66d327ef','Read “쭉 가세요. 오른쪽으로 가세요.”. Which meaning fits this exchange?','multiple_choice','Go straight. Turn/go right.','["Go straight. Turn/go right.","I am going to the station.","I take the subway. I get off at Seoul Station."]'::jsonb,'쪽 means side/direction. 왼쪽으로 가세요 means please go left. 으로/로 marks a direction or means. 쭉 가세요 means go straight along; it is not a fixed distance.',5) on conflict(id) do nothing;
