insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('1a8fc48d-be33-52c2-478c-f6a34a553f8a','4c601bfa-d57e-0a1b-995f-f557f24ef73e','Ace asks you to communicate: “Where is the restroom? It is inside the station.” Which Korean response fits?','multiple_choice','화장실이 어디에 있어요? 역 안에 있어요.','["화장실이 어디에 있어요? 역 안에 있어요.","역에 가요.","쭉 가세요. 오른쪽으로 가세요."]'::jsonb,'화장실이 어디에 있어요? 역 안에 있어요. — Where is the restroom? It is inside the station.. A location + 에 있어요 describes existence at that place. 이/가 marks the thing located: 화장실이 어디에 있어요? Use 앞에, 뒤에, 옆에 with a landmark.',4) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('5ef85167-3827-14fb-383a-16306d2ea716','4c601bfa-d57e-0a1b-995f-f557f24ef73e','Read “화장실이 어디에 있어요? 역 안에 있어요.”. Which meaning fits this exchange?','multiple_choice','Where is the restroom? It is inside the station.','["Where is the restroom? It is inside the station.","I am going to the station.","Go straight. Turn/go right."]'::jsonb,'A location + 에 있어요 describes existence at that place. 이/가 marks the thing located: 화장실이 어디에 있어요? Use 앞에, 뒤에, 옆에 with a landmark.',5) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('2f390699-aa55-a95f-07fa-cb79b5a159d2','4c601bfa-d57e-0a1b-995f-f557f24ef73e','Remember your visit to Gwangjang Market: what does “맛있어요” mean?','multiple_choice','It is delicious','["It is delicious","It does not taste good","It is spicy"]'::jsonb,'From “Tastes and Preferences”: 맛있어요 means It is delicious.',6) on conflict(id) do nothing;
