insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('6a8b8d8b-b706-b9d8-7ae3-45581a131159','7af6853a-6c65-ce59-16c6-2231b9416306','At Seoul Subway, what does “은행” communicate?','multiple_choice','bank','["bank","station","hotel"]'::jsonb,'은행: bank. Review the unit’s taught patterns. No new grammar is required.',3) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('32c693dd-87bc-2bf5-62d3-67b96af934a2','7af6853a-6c65-ce59-16c6-2231b9416306','Ace asks you to communicate: “I am going to the station.” Which Korean response fits?','multiple_choice','역에 가요.','["역에 가요.","쭉 가세요. 오른쪽으로 가세요.","지하철을 타요. 서울역에서 내려요."]'::jsonb,'역에 가요. — I am going to the station.. 에 marks a destination with 가요: 역에 가요. This differs from 에서, which marks where an action takes place. Learn the contrast explicitly before directions.',4) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('31fdbeec-2405-681b-c842-9471c88730fb','7af6853a-6c65-ce59-16c6-2231b9416306','Ace asks you to communicate: “Go straight. Turn/go right.” Which Korean response fits?','multiple_choice','쭉 가세요. 오른쪽으로 가세요.','["쭉 가세요. 오른쪽으로 가세요.","역에 가요.","지하철을 타요. 서울역에서 내려요."]'::jsonb,'쭉 가세요. 오른쪽으로 가세요. — Go straight. Turn/go right.. 쪽 means side/direction. 왼쪽으로 가세요 means please go left. 으로/로 marks a direction or means. 쭉 가세요 means go straight along; it is not a fixed distance.',5) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('3ab6c822-3d86-b739-856a-e9e9ead563ec','7af6853a-6c65-ce59-16c6-2231b9416306','Ace asks you to communicate: “I take the subway. I get off at Seoul Station.” Which Korean response fits?','multiple_choice','지하철을 타요. 서울역에서 내려요.','["지하철을 타요. 서울역에서 내려요.","역에 가요.","쭉 가세요. 오른쪽으로 가세요."]'::jsonb,'지하철을 타요. 서울역에서 내려요. — I take the subway. I get off at Seoul Station.. 을/를 타요 means take/ride a vehicle. 에서 내려요 marks where you get off. 버스를 타요 and 버스에서 내려요 use different particles for different roles.',6) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('8ada884c-53a9-de9b-128c-d097f6aa92ff','7af6853a-6c65-ce59-16c6-2231b9416306','Ace asks you to communicate: “Where is the restroom? It is inside the station.” Which Korean response fits?','multiple_choice','화장실이 어디에 있어요? 역 안에 있어요.','["화장실이 어디에 있어요? 역 안에 있어요.","역에 가요.","쭉 가세요. 오른쪽으로 가세요."]'::jsonb,'화장실이 어디에 있어요? 역 안에 있어요. — Where is the restroom? It is inside the station.. A location + 에 있어요 describes existence at that place. 이/가 marks the thing located: 화장실이 어디에 있어요? Use 앞에, 뒤에, 옆에 with a landmark.',7) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('a82cba73-340b-d7a1-911e-c9b04ee87c75','7af6853a-6c65-ce59-16c6-2231b9416306','Remember your visit to Gwangjang Market: what does “김밥” mean?','multiple_choice','gimbap (rice rolls)','["gimbap (rice rolls)","bibimbap (mixed rice)","tteokbokki (rice cakes in sauce)"]'::jsonb,'From “Popular Korean Foods”: 김밥 means gimbap (rice rolls).',8) on conflict(id) do nothing;
