insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('a2613a8c-5b0c-2b18-49fa-d92870911739','5a498c3c-7372-2dc1-3d00-b13a10cf5574','At Bukchon Hanok Village, what does “월요일” communicate?','multiple_choice','Monday','["Monday","Tuesday","Wednesday"]'::jsonb,'월요일: Monday. Review the unit’s taught patterns. No new grammar is required.',1) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('685c0bd7-e558-2c3f-b40b-f28c0ad9c392','5a498c3c-7372-2dc1-3d00-b13a10cf5574','At Bukchon Hanok Village, what does “화요일” communicate?','multiple_choice','Tuesday','["Tuesday","Monday","Wednesday"]'::jsonb,'화요일: Tuesday. Review the unit’s taught patterns. No new grammar is required.',2) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('1368e575-de54-872d-7901-84f3ab808f44','5a498c3c-7372-2dc1-3d00-b13a10cf5574','At Bukchon Hanok Village, what does “수요일” communicate?','multiple_choice','Wednesday','["Wednesday","Monday","Tuesday"]'::jsonb,'수요일: Wednesday. Review the unit’s taught patterns. No new grammar is required.',3) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('e79eaef4-0faf-963b-5cb3-00e23fd1477d','5a498c3c-7372-2dc1-3d00-b13a10cf5574','Ace asks you to communicate: “Today is Monday.” Which Korean response fits?','multiple_choice','오늘은 월요일이에요.','["오늘은 월요일이에요.","세 시 삼십 분이에요.","아침에 밥을 먹어요. 카페에서 공부해요."]'::jsonb,'오늘은 월요일이에요. — Today is Monday.. Use Sino-Korean numbers for dates. June and October have special month forms 유월 and 시월. 에 marks many time points, but not 오늘, 어제, 내일.',4) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('654d7e09-9acd-756a-9528-9f7d8ad0df30','5a498c3c-7372-2dc1-3d00-b13a10cf5574','Ace asks you to communicate: “It is three thirty.” Which Korean response fits?','multiple_choice','세 시 삼십 분이에요.','["세 시 삼십 분이에요.","오늘은 월요일이에요.","아침에 밥을 먹어요. 카페에서 공부해요."]'::jsonb,'세 시 삼십 분이에요. — It is three thirty.. Hours normally use native numbers and 시: 한 시, 두 시. Minutes use Sino-Korean numbers and 분: 십 분. 열두 시 is twelve o’clock; 반 means half past.',5) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('e7cb879a-ccda-2edd-be07-005a1fd447f5','5a498c3c-7372-2dc1-3d00-b13a10cf5574','Ace asks you to communicate: “I eat a meal in the morning. I study at a café.” Which Korean response fits?','multiple_choice','아침에 밥을 먹어요. 카페에서 공부해요.','["아침에 밥을 먹어요. 카페에서 공부해요.","오늘은 월요일이에요.","세 시 삼십 분이에요."]'::jsonb,'아침에 밥을 먹어요. 카페에서 공부해요. — I eat a meal in the morning. I study at a café.. Remove 다 from dictionary verbs, then learn the appropriate 아요/어요 pattern: 가다 → 가요, 먹다 → 먹어요, 하다 → 해요. 에서 marks the location of an action; 에 marks time.',6) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('732b4d47-3ad5-2b44-152d-68df0906378e','5a498c3c-7372-2dc1-3d00-b13a10cf5574','Ace asks you to communicate: “Yesterday I went to the market. I ate gimbap.” Which Korean response fits?','multiple_choice','어제 시장에 갔어요. 김밥을 먹었어요.','["어제 시장에 갔어요. 김밥을 먹었어요.","오늘은 월요일이에요.","세 시 삼십 분이에요."]'::jsonb,'어제 시장에 갔어요. 김밥을 먹었어요. — Yesterday I went to the market. I ate gimbap.. Past polite forms include 갔어요, 먹었어요, 했어요. Learn whole forms alongside stems; not every verb simply adds 었어요 unchanged. 어제 takes no time 에.',7) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('afb0fa04-e2fc-c169-c18b-f6c855aa64b5','5a498c3c-7372-2dc1-3d00-b13a10cf5574','Remember your visit to Seoul Subway: what does “역” mean?','multiple_choice','station','["station","hotel","bank"]'::jsonb,'From “Places Around the City”: 역 means station.',8) on conflict(id) do nothing;
