insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('ec0544fb-2308-8571-d1e7-f86bf3d590d2','7ab0e3c5-b4df-2030-a589-4e6a6fea8da2','Ace asks you to communicate: “Hello. Thank you.” Which Korean response fits?','multiple_choice','안녕하세요. 감사합니다.','["안녕하세요. 감사합니다.","성함이 어떻게 되세요?","사진을 찍어도 돼요?"]'::jsonb,'안녕하세요. 감사합니다. — Hello. Thank you.. 해요-style is everyday polite speech. 합니다-style is polite and more formal. 해-style is casual and requires an appropriate relationship. Speech level and honoring a sentence’s subject are related but different systems.',4) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('1e53ccce-fdb1-acb4-eb02-f532b22ee155','7ab0e3c5-b4df-2030-a589-4e6a6fea8da2','Ace asks you to communicate: “May I ask your name? (respectful)” Which Korean response fits?','multiple_choice','성함이 어떻게 되세요?','["성함이 어떻게 되세요?","안녕하세요. 감사합니다.","사진을 찍어도 돼요?"]'::jsonb,'성함이 어떻게 되세요? — May I ask your name? (respectful). 성함 is a respectful word for someone’s name. 주무세요 and 드세요 honor the subject; do not use them for your own sleeping or eating. Older does not mean every sentence needs maximal formality.',5) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('0ab95978-4ac7-8075-432d-3ed0a37ab072','7ab0e3c5-b4df-2030-a589-4e6a6fea8da2','Ace asks you to communicate: “May I take a photo?” Which Korean response fits?','multiple_choice','사진을 찍어도 돼요?','["사진을 찍어도 돼요?","안녕하세요. 감사합니다.","성함이 어떻게 되세요?"]'::jsonb,'사진을 찍어도 돼요? — May I take a photo?. 아/어도 돼요? asks permission: 찍어도 돼요? means may I take a photo? 안 돼요 means it is not permitted in this context, not simply I dislike it. Learn the full phrase before generalizing.',6) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('646166ff-0c6c-8b95-a682-378dc73da9eb','7ab0e3c5-b4df-2030-a589-4e6a6fea8da2','Ace asks you to communicate: “I meet family at Chuseok.” Which Korean response fits?','multiple_choice','추석에 가족을 만나요.','["추석에 가족을 만나요.","안녕하세요. 감사합니다.","성함이 어떻게 되세요?"]'::jsonb,'추석에 가족을 만나요. — I meet family at Chuseok.. 에 can mark a holiday or event time: 설날에. Families and individuals celebrate differently. Avoid statements that every Korean follows a single custom.',7) on conflict(id) do nothing;
