insert into public.activities(id,lesson_id,title,instructions,activity_type,activity_order) values('5ec296f5-5a2f-9b38-8f57-3bb3f82cfce5','384bb894-390c-176b-bebf-03993226ff95','Notice, understand, and speak','날씨가 좋아요 describes nice weather. 비가 와요 literally uses rain as the subject. 춥다 → 추워요 and 덥다 → 더워요 are irregular forms; do not add an extra 이에요.
