insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('4838edb5-277a-1e74-44bd-3c43dde9a5f8','c9fa35ac-1e01-15ad-b9f7-f74b849aaef7','Ace asks you to communicate: “It is raining today. It is a little cold.” Which Korean response fits?','multiple_choice','오늘은 비가 와요. 조금 추워요.','["오늘은 비가 와요. 조금 추워요.","부산 바다가 정말 예뻐요.","내일 해운대에 갈 거예요."]'::jsonb,'오늘은 비가 와요. 조금 추워요. — It is raining today. It is a little cold.. 날씨가 좋아요 describes nice weather. 비가 와요 literally uses rain as the subject. 춥다 → 추워요 and 덥다 → 더워요 are irregular forms; do not add an extra 이에요.',4) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('a0bdf181-4dc5-bd17-3b64-6fe5eae14d38','c9fa35ac-1e01-15ad-b9f7-f74b849aaef7','Read “오늘은 비가 와요. 조금 추워요.”. Which meaning fits this exchange?','multiple_choice','It is raining today. It is a little cold.','["It is raining today. It is a little cold.","The sea in Busan is really beautiful.","I am going to go to Haeundae tomorrow."]'::jsonb,'날씨가 좋아요 describes nice weather. 비가 와요 literally uses rain as the subject. 춥다 → 추워요 and 덥다 → 더워요 are irregular forms; do not add an extra 이에요.',5) on conflict(id) do nothing;
