insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('d7d9317c-7008-f7da-3a67-e8d5ef28a609','e67a9d5b-be45-0ac3-b744-8772aa3d2075','At Busan, what does “봄” communicate?','multiple_choice','spring','["spring","summer","autumn"]'::jsonb,'봄: spring. Review the unit’s taught patterns. No new grammar is required.',1) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('1f407a8a-6575-2180-8dad-aa4ed8210ab4','e67a9d5b-be45-0ac3-b744-8772aa3d2075','At Busan, what does “여름” communicate?','multiple_choice','summer','["summer","spring","autumn"]'::jsonb,'여름: summer. Review the unit’s taught patterns. No new grammar is required.',2) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('de61d20a-0c95-2a9b-c127-dcafcb80ec61','e67a9d5b-be45-0ac3-b744-8772aa3d2075','At Busan, what does “가을” communicate?','multiple_choice','autumn','["autumn","spring","summer"]'::jsonb,'가을: autumn. Review the unit’s taught patterns. No new grammar is required.',3) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('e99daf7c-e04a-26d9-3d07-17caa6111f44','e67a9d5b-be45-0ac3-b744-8772aa3d2075','Ace asks you to communicate: “It is raining today. It is a little cold.” Which Korean response fits?','multiple_choice','오늘은 비가 와요. 조금 추워요.','["오늘은 비가 와요. 조금 추워요.","부산 바다가 정말 예뻐요.","내일 해운대에 갈 거예요."]'::jsonb,'오늘은 비가 와요. 조금 추워요. — It is raining today. It is a little cold.. 날씨가 좋아요 describes nice weather. 비가 와요 literally uses rain as the subject. 춥다 → 추워요 and 덥다 → 더워요 are irregular forms; do not add an extra 이에요.',4) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('3ff93ea9-8b83-3ac9-2b92-0edd979d2e3d','e67a9d5b-be45-0ac3-b744-8772aa3d2075','Ace asks you to communicate: “The sea in Busan is really beautiful.” Which Korean response fits?','multiple_choice','부산 바다가 정말 예뻐요.','["부산 바다가 정말 예뻐요.","오늘은 비가 와요. 조금 추워요.","내일 해운대에 갈 거예요."]'::jsonb,'부산 바다가 정말 예뻐요. — The sea in Busan is really beautiful.. 예뻐요, 커요, and 조용해요 work as predicates without 이다. 정말 intensifies an impression. Use 은/는 for a topic and 이/가 for an identified subject without treating either as an English word.',5) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('774f3dd8-2e5f-1058-0289-479705fcb72d','e67a9d5b-be45-0ac3-b744-8772aa3d2075','Ace asks you to communicate: “I am going to go to Haeundae tomorrow.” Which Korean response fits?','multiple_choice','내일 해운대에 갈 거예요.','["내일 해운대에 갈 거예요.","오늘은 비가 와요. 조금 추워요.","부산 바다가 정말 예뻐요."]'::jsonb,'내일 해운대에 갈 거예요. — I am going to go to Haeundae tomorrow.. Use verb stem + (으)ㄹ 거예요: 가다 → 갈 거예요, 먹다 → 먹을 거예요, 하다 → 할 거예요. This often expresses an intention or prediction, not an absolute promise. 내일 takes no 에.',6) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('9b10326d-eab0-279f-358b-f11d79427e41','e67a9d5b-be45-0ac3-b744-8772aa3d2075','Ace asks you to communicate: “Yesterday I went to the sea. Tomorrow I am going to the market.” Which Korean response fits?','multiple_choice','어제 바다에 갔어요. 내일 시장에 갈 거예요.','["어제 바다에 갔어요. 내일 시장에 갈 거예요.","오늘은 비가 와요. 조금 추워요.","부산 바다가 정말 예뻐요."]'::jsonb,'어제 바다에 갔어요. 내일 시장에 갈 거예요. — Yesterday I went to the sea. Tomorrow I am going to the market.. Combine learned past and future forms in separate short sentences. 정말 재미있었어요 describes your impression; it does not mean every traveler has the same experience. Avoid new relative clauses here.',7) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('54855699-fd2b-117b-5896-3c64643555ff','e67a9d5b-be45-0ac3-b744-8772aa3d2075','Remember your visit to Gyeongbokgung Palace: what does “안녕하세요” mean?','multiple_choice','hello (polite)','["hello (polite)","thank you (formal polite)","thank you (polite)"]'::jsonb,'From “Respectful Speech in Korea”: 안녕하세요 means hello (polite).',8) on conflict(id) do nothing;
