insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('3f8e02df-25d3-3d1a-5baf-7ce16fdb00ba','d838e09b-af49-315f-f902-d14a42b2f735','Ace asks you to communicate: “Hello. I am Minsu. I came from the Philippines.” Which Korean response fits?','multiple_choice','안녕하세요. 저는 민수예요. 필리핀에서 왔어요.','["안녕하세요. 저는 민수예요. 필리핀에서 왔어요.","커피 두 잔 주세요. 이거 얼마예요?","저는 카페에서 한국어를 공부해요."]'::jsonb,'안녕하세요. 저는 민수예요. 필리핀에서 왔어요. — Hello. I am Minsu. I came from the Philippines.. Review greetings, topic 은/는, identification 이에요/예요, and positive questions. Choose the appropriate level of politeness for a new guide.',4) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('f5da56ec-5443-ff16-0f06-02963804cbc0','d838e09b-af49-315f-f902-d14a42b2f735','Ace asks you to communicate: “Two coffees, please. How much is this?” Which Korean response fits?','multiple_choice','커피 두 잔 주세요. 이거 얼마예요?','["커피 두 잔 주세요. 이거 얼마예요?","안녕하세요. 저는 민수예요. 필리핀에서 왔어요.","저는 카페에서 한국어를 공부해요."]'::jsonb,'커피 두 잔 주세요. 이거 얼마예요? — Two coffees, please. How much is this?. Review 주세요, counters, Sino-Korean prices, destination 에, and action location 에서. Keep noun-counter order: 커피 두 잔.',5) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('ff3b4391-675e-fa4d-6cc6-8a5d3f1f8413','d838e09b-af49-315f-f902-d14a42b2f735','Ace asks you to communicate: “I study Korean at a café.” Which Korean response fits?','multiple_choice','저는 카페에서 한국어를 공부해요.','["저는 카페에서 한국어를 공부해요.","안녕하세요. 저는 민수예요. 필리핀에서 왔어요.","커피 두 잔 주세요. 이거 얼마예요?"]'::jsonb,'저는 카페에서 한국어를 공부해요. — I study Korean at a café.. Review syllable blocks, batchim, spacing, particles, and polite endings. Romanization is hidden by default here; use Hangul and the optional writing studio.',6) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('a1df0652-076e-da47-e8d3-670a5d98afc8','d838e09b-af49-315f-f902-d14a42b2f735','Ace asks you to communicate: “Yesterday I went to the market. Tomorrow I will go to the palace.” Which Korean response fits?','multiple_choice','어제 시장에 갔어요. 내일 궁궐에 갈 거예요.','["어제 시장에 갔어요. 내일 궁궐에 갈 거예요.","안녕하세요. 저는 민수예요. 필리핀에서 왔어요.","커피 두 잔 주세요. 이거 얼마예요?"]'::jsonb,'어제 시장에 갔어요. 내일 궁궐에 갈 거예요. — Yesterday I went to the market. Tomorrow I will go to the palace.. Choose a form for the situation instead of translating English word by word. Reuse 안, past 았/었어요, and future (으)ㄹ 거예요; do not introduce new grammar in the finale.',7) on conflict(id) do nothing;
insert into public.questions(id,activity_id,question_text,question_type,correct_answer,options,explanation,question_order) values('2f27fc06-769f-e02e-f296-895d3f758cc8','d838e09b-af49-315f-f902-d14a42b2f735','Remember your visit to Busan: what does “봄” mean?','multiple_choice','spring','["spring","summer","autumn"]'::jsonb,'From “Weather and Seasons”: 봄 means spring.',8) on conflict(id) do nothing;
insert into public.travel_country_units(country_id,unit_id,is_required) values('d3c981a5-9bf7-469c-93de-8a7c5105c6eb','a0d64bf0-11d0-ea8a-20f5-e0a4332e5cc8',true) on conflict do nothing;
insert into public.travel_unit_curriculum(unit_id,slug,cultural_introduction,learning_objectives,challenge_lesson_id,writing_recommendation,estimated_minutes) values('a0d64bf0-11d0-ea8a-20f5-e0a4332e5cc8','ko-n-seoul-tower','Use what you know to solve everyday travel tasks. Ask for clarification rather than pretending to understand.','["Greet, introduce yourself, and ask a follow-up question.","Order, pay, and ask for directions in sequence.","Read signs and compose short sentences in Hangul.","Combine requests, permission, past experience, and a plan."]'::jsonb,'6a8ceefe-09e2-5408-8dae-f24e1e52d5eb','Open the Korean Hangul workbook for the matching stage; verified stroke assets require review.',90) on conflict(unit_id) do nothing;
insert into public.passport_stamp_definitions(id,country_id,unit_id,slug,name,description,requirement_type,is_active) select '6fc15074-2aa6-7ecb-30e3-8e30a8598842','d3c981a5-9bf7-469c-93de-8a7c5105c6eb','a0d64bf0-11d0-ea8a-20f5-e0a4332e5cc8','ko-n-seoul-tower','N Seoul Tower Explorer','Complete the published lessons and destination challenge at N Seoul Tower.','unit_completion',false where not exists(select 1 from public.passport_stamp_definitions where country_id='d3c981a5-9bf7-469c-93de-8a7c5105c6eb' and unit_id='a0d64bf0-11d0-ea8a-20f5-e0a4332e5cc8' and requirement_type='unit_completion') on conflict do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) values('3556cb6b-f953-abc9-a8d3-1d4b6deb27d7','c3792eee-2458-45aa-859e-81e243a78c17','ko-hangul-introduction','Meet Hangul','1 · Introduction to Hangul','Read a syllable block and discover the jobs of its letters.','[{"title":"Letters form blocks","text":"Hangul is an alphabet whose letters combine into syllable blocks. Each block has an initial consonant and a vowel; a final consonant is optional. Read blocks left to right in ordinary horizontal text.","korean":"한글","reading":"hangeul","translation":"Hangul"},{"title":"Silent first, audible last","text":"ㅇ is silent at the beginning of 아, but sounds like ng at the end of 강. Its position changes its role.","korean":"아 · 강"},{"title":"Writing and sound","text":"Romanization is a temporary reading aid. Korean sounds do not map perfectly to English letters. Audio uses a Korean device voice when available; it is not a verified recording. Stroke demonstrations require verified assets; unverified paths are never supplied."}]'::jsonb,0,false) on conflict(language_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '22c36512-ceeb-86a6-2d27-e5e69e9dbca1',id,'blocks','choice','{"slug":"blocks","kind":"choice","prompt":"What does one Hangul block usually represent?","choices":["A syllable","A whole English sentence","One Latin letter"],"answer":"A syllable","explanation":"A block combines consonant and vowel letters.","languageCode":"ko"}'::jsonb,0,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-hangul-introduction' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '9da07ea1-db8b-c9c5-a667-80e1592d0de1',id,'ieung','choice','{"slug":"ieung","kind":"choice","prompt":"What is initial ㅇ doing in 아?","choices":["A silent initial placeholder","An ng sound","A final consonant"],"answer":"A silent initial placeholder","explanation":"Final ㅇ is ng, but initial ㅇ is silent.","languageCode":"ko"}'::jsonb,1,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-hangul-introduction' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) values('6a6b8e78-23c9-6b18-8205-c90578eab694','c3792eee-2458-45aa-859e-81e243a78c17','ko-basic-consonants','Basic consonants','2 · Basic consonants','Recognize fourteen basic consonants in short words.','[{"title":"Your basic consonants","text":"Read ㄱ ㄴ ㄷ ㄹ ㅁ ㅂ ㅅ ㅇ ㅈ ㅊ ㅋ ㅌ ㅍ ㅎ. Their names and sounds are different: ㄱ is called 기역, but that name is not the sound you insert into a word.","korean":"ㄱ ㄴ ㄷ ㄹ ㅁ ㅂ ㅅ ㅇ ㅈ ㅊ ㅋ ㅌ ㅍ ㅎ"},{"title":"Learn sounds in words","text":"ㄱ varies with position and is not always English g. ㄹ can be a short tap or an l-like sound. Aspirated ㅋ ㅌ ㅍ ㅊ have a stronger puff than their plain counterparts. Use the character cards for examples and recall mastery.","korean":"가 · 나 · 마","reading":"ga · na · ma"}]'::jsonb,1,false) on conflict(language_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select 'bdec1ee2-58f2-0256-1d11-e6ca2803c28d',id,'mieum','choice','{"slug":"mieum","kind":"choice","prompt":"Which consonant begins 마?","choices":["ㅁ","ㄴ","ㄱ"],"answer":"ㅁ","explanation":"마 is ㅁ plus ㅏ.","languageCode":"ko"}'::jsonb,0,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-basic-consonants' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '646c3cf6-7a08-357e-c175-5e9fcf3b2cab',id,'nieun','choice','{"slug":"nieun","kind":"choice","prompt":"Which consonant begins 나무 (tree)?","choices":["ㄴ","ㅂ","ㅅ"],"answer":"ㄴ","explanation":"나 begins with ㄴ.","languageCode":"ko"}'::jsonb,1,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-basic-consonants' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select 'a165dbe6-a3be-7fd3-96fb-a04aea6bd499',id,'aspirated','choice','{"slug":"aspirated","kind":"choice","prompt":"Which is the aspirated counterpart of ㄱ?","choices":["ㅋ","ㄲ","ㄴ"],"answer":"ㅋ","explanation":"ㅋ is aspirated; ㄲ is tense, not the same contrast.","languageCode":"ko"}'::jsonb,2,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-basic-consonants' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) values('7d33c945-8a70-6b23-dfea-d30b93cc5aff','c3792eee-2458-45aa-859e-81e243a78c17','ko-basic-vowels','Basic vowels','3 · Basic vowels','Recognize ten basic vowels and their orientation.','[{"title":"Ten basic vowels","text":"Learn ㅏ ㅑ ㅓ ㅕ ㅗ ㅛ ㅜ ㅠ ㅡ ㅣ. A vertical vowel usually sits beside the consonant; a horizontal vowel usually sits underneath it.","korean":"아 야 어 여 오 요 우 유 으 이","reading":"a ya eo yeo o yo u yu eu i"},{"title":"Distinguish rather than guess","text":"ㅓ (eo) is not the same as ㅗ (o). ㅡ (eu) is not English oo. Listen when a Korean voice is available and compare 우 and 으; romanization alone cannot teach the contrast.","korean":"어 · 오 · 우 · 으"}]'::jsonb,2,false) on conflict(language_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select 'a2da5a4e-d156-d493-fca7-db93674b7dbd',id,'o','choice','{"slug":"o","kind":"choice","prompt":"Which block contains ㅗ?","choices":["오","어","우"],"answer":"오","explanation":"오 combines silent ㅇ and ㅗ.","languageCode":"ko"}'::jsonb,0,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-basic-vowels' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select 'f35169fe-f78e-588c-fbec-15677221391d',id,'eu','choice','{"slug":"eu","kind":"choice","prompt":"Which block contains ㅡ?","choices":["으","우","이"],"answer":"으","explanation":"으 has the vowel eu.","languageCode":"ko"}'::jsonb,1,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-basic-vowels' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select 'fb8db745-f161-f6f4-aaf1-1333d286c698',id,'vertical','choice','{"slug":"vertical","kind":"choice","prompt":"Which vowel normally goes to the right of the initial consonant?","choices":["ㅏ","ㅗ","ㅡ"],"answer":"ㅏ","explanation":"Compare 가 and 고.","languageCode":"ko"}'::jsonb,2,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-basic-vowels' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) values('73c5e766-0409-d9ca-3c67-45e4fc24f113','c3792eee-2458-45aa-859e-81e243a78c17','ko-syllable-blocks','Build syllable blocks','4 · Syllable blocks','Combine consonants and vowels into readable words.','[{"title":"Beside or underneath","text":"ㄴ + ㅏ becomes 나. ㄱ + ㅗ becomes 고. These letters share one block, rather than being written as a row of separate letters.","korean":"나 · 고"},{"title":"Read meaningful words","text":"나무 has two blocks, 나 and 무. 바다 means sea. 우유 means milk. A word can have several syllables; a syllable does not automatically have its own English meaning.","korean":"나무 · 바다 · 우유","reading":"namu · bada · uyu","translation":"tree · sea · milk"}]'::jsonb,3,false) on conflict(language_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '32c96965-f2cf-9770-c561-bfe4144e1f1a',id,'assemble','choice','{"slug":"assemble","kind":"choice","prompt":"What is ㄴ + ㅏ in one block?","choices":["나","고","무"],"answer":"나","explanation":"The vertical vowel is beside ㄴ.","languageCode":"ko"}'::jsonb,0,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-syllable-blocks' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '1a2042c0-c70f-f20d-0fb4-90a35f56ce40',id,'tree','word','{"slug":"tree","kind":"word","languageCode":"ko","prompt":"Build 나무 (tree) from syllable tiles.","answer":"나무","tiles":["무","나"],"explanation":"나 + 무 forms 나무, tree."}'::jsonb,1,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-syllable-blocks' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '8648756f-53df-7aef-c911-cd3ab1aa03b0',id,'blocks-count','choice','{"slug":"blocks-count","kind":"choice","prompt":"How many syllable blocks are in 우유?","choices":["Two","One","Four"],"answer":"Two","explanation":"우 and 유 are separate blocks.","languageCode":"ko"}'::jsonb,2,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-syllable-blocks' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) values('4ffbb760-d32a-27db-5811-8a78b8a9d0c2','c3792eee-2458-45aa-859e-81e243a78c17','ko-batchim','Final consonants: batchim','5 · Final consonants (batchim)','Read a final consonant and notice connected pronunciation.','[{"title":"The bottom position","text":"받침 is the final consonant position below the vowel. In 강, ㅇ is the final ng. In 산, ㄴ is the final n.","korean":"강 · 산 · 밥","reading":"gang · san · bap","translation":"river · mountain · cooked rice / meal"},{"title":"Spelling and connected sound","text":"Several written finals share the same unreleased final sound. When followed by a vowel-initial syllable, a final consonant may connect to it: 밥을 is pronounced 바블. Double finals and sound changes need word-specific study; do not pronounce every final with an extra vowel.","korean":"밥을","reading":"babeul"}]'::jsonb,4,false) on conflict(language_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select 'ff403857-b88a-67f7-d733-d3328e3f67bf',id,'final','choice','{"slug":"final","kind":"choice","prompt":"What is the batchim in 강?","choices":["ㅇ","ㄱ","ㅏ"],"answer":"ㅇ","explanation":"The bottom ㅇ is ng.","languageCode":"ko"}'::jsonb,0,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-batchim' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '0825a0af-c448-df3a-66b3-c00cd76a1b9b',id,'san','choice','{"slug":"san","kind":"choice","prompt":"Which word means mountain?","choices":["산","강","나무"],"answer":"산","explanation":"산 ends with ㄴ.","languageCode":"ko"}'::jsonb,1,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-batchim' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select 'c636f47a-bcf7-3f5e-68fb-49d6faca28ae',id,'no-vowel','choice','{"slug":"no-vowel","kind":"choice","prompt":"How should a final consonant be practiced?","choices":["Without adding an extra vowel","Always add eu","Always ignore it"],"answer":"Without adding an extra vowel","explanation":"Learn the final and its connected pronunciation in a word.","languageCode":"ko"}'::jsonb,2,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-batchim' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) values('68794b27-c045-2dba-d769-89d2dbf786cc','c3792eee-2458-45aa-859e-81e243a78c17','ko-compound-vowels','Compound vowels','6 · Compound vowels','Read common compound vowels in everyday words.','[{"title":"Combine vowel shapes","text":"Learn ㅐ ㅒ ㅔ ㅖ ㅘ ㅙ ㅚ ㅝ ㅞ ㅟ ㅢ. In modern speech ㅐ and ㅔ may sound alike for many speakers; keep the spelling distinction.","korean":"개 · 게 · 와 · 워 · 위"},{"title":"Read in context","text":"과자 includes ㅘ, 귀 includes ㅟ, and 의자 begins with ㅢ. The pronunciation of ㅢ varies with position and grammatical use; learn 의자 as a whole word before particle 의.","korean":"과자 · 귀 · 의자","reading":"gwaja · gwi · uija","translation":"snack · ear · chair"}]'::jsonb,5,false) on conflict(language_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '1c2e430f-85f3-2f98-227c-4cff85f36e6f',id,'wa','choice','{"slug":"wa","kind":"choice","prompt":"Which block contains ㅘ?","choices":["와","워","위"],"answer":"와","explanation":"ㅗ plus ㅏ forms ㅘ.","languageCode":"ko"}'::jsonb,0,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-compound-vowels' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '91a745f0-9686-8a1c-3ccc-20d025058367',id,'chair','choice','{"slug":"chair","kind":"choice","prompt":"Which word means chair?","choices":["의자","과자","귀"],"answer":"의자","explanation":"의자 begins with ㅢ.","languageCode":"ko"}'::jsonb,1,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-compound-vowels' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '0c961f1b-d12b-b3c0-775f-997ed4d0a79b',id,'spelling','choice','{"slug":"spelling","kind":"choice","prompt":"If ㅐ and ㅔ sound similar, should their spellings be merged?","choices":["No, retain the word’s spelling","Yes, either is always correct"],"answer":"No, retain the word’s spelling","explanation":"Pronunciation overlap does not erase spelling distinctions.","languageCode":"ko"}'::jsonb,2,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-compound-vowels' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) values('72626880-f205-d2a4-7db4-a2342ae87d1a','c3792eee-2458-45aa-859e-81e243a78c17','ko-tense-consonants','Tense consonants','7 · Tense consonants','Distinguish plain, aspirated, and tense consonants.','[{"title":"Five tense consonants","text":"ㄲ ㄸ ㅃ ㅆ ㅉ are tense consonants. They are not simply longer English consonants, and not the same as aspirated ㅋ ㅌ ㅍ ㅊ. Listen to complete words before trying to explain the contrast using English letters.","korean":"ㄲ ㄸ ㅃ ㅆ ㅉ"},{"title":"The contrast can change meaning","text":"달 is moon; 딸 is daughter. 쌀 is uncooked rice, while 살 has several meanings, including flesh and the age counter. Learn the intended meaning in context.","korean":"달 · 딸 · 쌀","reading":"dal · ttal · ssal","translation":"moon · daughter · uncooked rice"}]'::jsonb,6,false) on conflict(language_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select 'bdb704ac-1ea2-8507-d98b-0233efe26338',id,'daughter','choice','{"slug":"daughter","kind":"choice","prompt":"Which word means daughter?","choices":["딸","달","탈"],"answer":"딸","explanation":"딸 begins with tense ㄸ.","languageCode":"ko"}'::jsonb,0,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-tense-consonants' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select 'b08cef02-5e2f-2688-2fd2-22915ddcb5a4',id,'rice','choice','{"slug":"rice","kind":"choice","prompt":"Which word means uncooked rice?","choices":["쌀","살","산"],"answer":"쌀","explanation":"쌀 begins with tense ㅆ.","languageCode":"ko"}'::jsonb,1,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-tense-consonants' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select 'c83fc3f9-dfe8-c1f6-2734-c9590a91bbf5',id,'tense','choice','{"slug":"tense","kind":"choice","prompt":"Which consonant is tense?","choices":["ㅃ","ㅍ","ㅂ"],"answer":"ㅃ","explanation":"ㅂ is plain, ㅍ aspirated, and ㅃ tense.","languageCode":"ko"}'::jsonb,2,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-tense-consonants' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) values('82a4da6a-d41f-aefd-53be-b430ee6cc104','c3792eee-2458-45aa-859e-81e243a78c17','ko-reading-words','Read Korean words','8 · Reading Korean words','Decode useful signs and practice comprehension.','[{"title":"A sign-reading mission","text":"Read without romanization first. 입구 is entrance, 출구 is exit, and 약국 is pharmacy. 서울역 is Seoul Station; its connected pronunciation differs from spelling letter by letter.","korean":"입구 · 출구 · 약국 · 서울역","translation":"entrance · exit · pharmacy · Seoul Station"},{"title":"Reading before speed","text":"Break unfamiliar words into blocks, connect them, then check meaning. If your device has no Korean voice, read aloud yourself; silent reading is not proof of listening comprehension."}]'::jsonb,7,false) on conflict(language_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '19168bd4-db3a-d7dc-e1ca-18218e908e3c',id,'exit','choice','{"slug":"exit","kind":"choice","prompt":"Which sign leads to the exit?","choices":["출구","입구","약국"],"answer":"출구","explanation":"출구 is exit; 입구 is entrance.","languageCode":"ko"}'::jsonb,0,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-reading-words' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '2d196cd1-fde5-f88f-5b19-ff67b6860b9e',id,'pharmacy','choice','{"slug":"pharmacy","kind":"choice","prompt":"You need a pharmacy. Which sign do you seek?","choices":["약국","서울역","출구"],"answer":"약국","explanation":"약국 is a pharmacy.","languageCode":"ko"}'::jsonb,1,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-reading-words' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '6553d498-72ea-905c-428e-5dcf19615ffc',id,'station','choice','{"slug":"station","kind":"choice","prompt":"Which word includes station?","choices":["서울역","우유","나무"],"answer":"서울역","explanation":"역 means station.","languageCode":"ko"}'::jsonb,2,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-reading-words' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) values('6c069ba0-6322-b8bc-77a6-59bf113411df','c3792eee-2458-45aa-859e-81e243a78c17','ko-writing-vocabulary','Write useful vocabulary','9 · Writing vocabulary','Rebuild familiar words, type them, and compare your handwriting.','[{"title":"Read, build, type, recall","text":"Begin with tiles, then type the same word using a Korean keyboard, then choose independent mode. Korean input normally composes jamo into NFC syllables. Finish IME composition before checking.","korean":"한국어 · 가방 · 학교 · 커피"},{"title":"Honest handwriting feedback","text":"Independent mode includes an optional drawing canvas. Compare with a printed model yourself. This records self-reviewed practice only; it is not stroke-order verification, automatic handwriting recognition, or a currency reward."}]'::jsonb,8,false) on conflict(language_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '8a128bf2-6dd3-ef4b-aa07-6e531365b400',id,'language','word','{"slug":"language","kind":"word","languageCode":"ko","prompt":"Build 한국어 (Korean language).","answer":"한국어","tiles":["어","한","국"],"explanation":"한 + 국 + 어 forms 한국어."}'::jsonb,0,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-writing-vocabulary' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select 'b445a86f-2983-c03f-cc26-949b25efff01',id,'bag','word','{"slug":"bag","kind":"word","languageCode":"ko","prompt":"Type 가방 (bag), then try independent mode.","answer":"가방","tiles":["방","가"],"responseMode":"typing","hint":"가 + 방","explanation":"가방 has two blocks."}'::jsonb,1,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-writing-vocabulary' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select 'ed90a9a9-e7f1-006b-6538-e65355a29ca7',id,'coffee','word','{"slug":"coffee","kind":"word","languageCode":"ko","prompt":"Write 커피 (coffee) independently.","answer":"커피","tiles":["피","커"],"responseMode":"independent","hint":"커 + 피","explanation":"Use the model to self-review the two blocks."}'::jsonb,2,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-writing-vocabulary' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_lessons(id,language_id,slug,title,stage,description,blocks,display_order,is_published) values('764d26c8-ede4-f60b-2f66-48fb9ec206ef','c3792eee-2458-45aa-859e-81e243a78c17','ko-building-sentences','Build Korean sentences','10 · Building Korean sentences','Move from guided explanations to tiles, gap filling, independent typing, and optional handwriting.','[{"title":"Level 1 · Understand the roles","text":"Korean normally places the predicate last. 저는 is a topic; 제가 is a subject form. 은/는 follows a final consonant/vowel respectively. 이/가 follows a final consonant/vowel respectively. 을/를 marks many objects. Topics are not simply the same thing as subjects.","korean":"저는 책을 읽어요.","translation":"I read a book."},{"title":"Level 2 · Arrange words","text":"Build a complete model with tiles. 학생이에요 follows a final consonant; 가수예요 follows a vowel. Polite questions can keep statement order and use rising intonation.","korean":"저는 학생이에요.","translation":"I am a student."},{"title":"Level 3 · Fill a gap","text":"For the gap 저는 커피를 ___, supply 마셔요. 먹다 → 먹어요, 가다 → 가요, 하다 → 해요. Place 안 before an ordinary verb to negate it: 안 마셔요. Do not replace a noun negation 학생이 아니에요 with 안 학생이에요."},{"title":"Level 4 · Write independently","text":"Time often comes early. 에 marks destination or many time points; 에서 marks where an action occurs. 어제 and 내일 take no time 에. Past 가다 → 갔어요; future 가다 → 갈 거예요, 먹다 → 먹을 거예요.","korean":"어제 카페에서 공부했어요.","translation":"Yesterday I studied at a café."},{"title":"Level 5 · Optional handwriting","text":"In independent mode, write on the canvas or on paper and compare to the model. Account completion records practice, not verified penmanship. Stroke order remains review-required until sourced assets are attached."}]'::jsonb,9,false) on conflict(language_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '2a5e74ed-6f91-7f60-ae31-0b6fd5efff86',id,'particle-roles','choice','{"slug":"particle-roles","kind":"choice","prompt":"In 저는 책을 읽어요, what does 을 mark?","choices":["The object 책","A future tense","The polite ending"],"answer":"The object 책","explanation":"책 ends in a consonant, so it takes 을.","languageCode":"ko"}'::jsonb,0,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-building-sentences' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '9d7c75dd-01ed-0e00-8878-12c04fdb3087',id,'student','sentence','{"slug":"student","kind":"sentence","prompt":"Arrange: I am a student.","answer":"저는 학생이에요.","tiles":["저는 ","학생이에요."],"explanation":"학생 ends in a consonant: 학생이에요.","languageCode":"ko","ending":"이에요"}'::jsonb,1,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-building-sentences' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '978b00d8-70fc-83cd-426a-129a4291d946',id,'gap-drink','sentence','{"slug":"gap-drink","kind":"sentence","prompt":"Fill the gap: 저는 커피를 ___. Type only the missing polite verb for drink.","answer":"마셔요","tiles":["마셔요"],"explanation":"마시다 becomes 마셔요.","languageCode":"ko","responseMode":"typing","hint":"마시다 → 마셔요"}'::jsonb,2,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-building-sentences' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '85936cd0-54d0-68fe-e647-db8ebf1c0097',id,'subject','sentence','{"slug":"subject","kind":"sentence","prompt":"Arrange: There is a book here.","answer":"여기에 책이 있어요.","tiles":["여기에 ","책이 ","있어요."],"explanation":"책 takes subject 이; 에 marks its location.","languageCode":"ko","requiredParticle":"이"}'::jsonb,3,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-building-sentences' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select '80563728-713c-1776-4400-699c66244bd2',id,'negative','sentence','{"slug":"negative","kind":"sentence","prompt":"Write: I do not drink coffee.","answer":"저는 커피를 안 마셔요.","tiles":["저는 ","커피를 ","안 ","마셔요."],"explanation":"안 negates 마셔요. The topic may be omitted when clear.","languageCode":"ko","alternatives":["커피를 안 마셔요."],"responseMode":"independent","requiredParticle":"를"}'::jsonb,4,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-building-sentences' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select 'a0e17c31-cb74-7e4a-2876-884dc317f294',id,'question','sentence','{"slug":"question","kind":"sentence","prompt":"Arrange the question: Where is the restroom?","answer":"화장실이 어디에 있어요?","tiles":["화장실이 ","어디에 ","있어요?"],"explanation":"이 marks the subject and 에 the location.","languageCode":"ko"}'::jsonb,5,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-building-sentences' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select 'ba757f44-8895-c319-8953-00a28637b8fc',id,'past','sentence','{"slug":"past","kind":"sentence","prompt":"Write: Yesterday I studied at a café.","answer":"어제 카페에서 공부했어요.","tiles":["어제 ","카페에서 ","공부했어요."],"explanation":"Use 에서 for the action location and 했어요 for past 하다.","languageCode":"ko","responseMode":"independent","requiredParticle":"에서","ending":"했어요"}'::jsonb,6,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-building-sentences' on conflict(lesson_id,slug) do nothing;
insert into public.writing_studio_activities(id,lesson_id,slug,kind,definition,display_order,is_published) select 'a85b0aa3-1bb8-d656-75dd-3237634160e1',id,'future','sentence','{"slug":"future","kind":"sentence","prompt":"Write: Tomorrow I will go to school.","answer":"내일 학교에 갈 거예요.","tiles":["내일 ","학교에 ","갈 거예요."],"explanation":"에 marks the destination; 갈 거예요 expresses the plan.","languageCode":"ko","responseMode":"independent","requiredParticle":"에","ending":"거예요"}'::jsonb,7,false from public.writing_studio_lessons where language_id='c3792eee-2458-45aa-859e-81e243a78c17' and slug='ko-building-sentences' on conflict(lesson_id,slug) do nothing;
